public static boolean tryCoverTimeBarInfo(ArrayList<TimeBarInfo> arrayList, TimeBarInfo timeBarInfo) {
    ArrayList<TimeBarInfo> arrayListCoverTimeBarInfo = coverTimeBarInfo(arrayList, timeBarInfo);
    if (arrayListCoverTimeBarInfo.size() <= 5) {
        arrayList.clear();
        arrayList.addAll(arrayListCoverTimeBarInfo);
        return true;
    }
    LogUtil.i(TAG, "<literal omitted>" + arrayListCoverTimeBarInfo.size() + arrayListCoverTimeBarInfo);
    return false;
}
